/* Conceptual DB Selection Guide */
CP Systems: Banking, Payment Processing, Financial Ledger (Strict Consistency)
AP Systems: Social Media Feeds, Product Reviews, Real-time Analytics (Eventual Consistency)

// Cache-Aside Pattern Implementation
async function getUser(userId) {
  const cachedUser = await redis.get(`user:${userId}`);
  if (cachedUser) return JSON.parse(cachedUser);

  const dbUser = await db.query('SELECT * FROM users WHERE id = ?', [userId]);
  if (dbUser) {
    await redis.setex(`user:${userId}`, 3600, JSON.stringify(dbUser));
  }
  return dbUser;
}
